const { owner_id = '', dias = 90 } = query;
const supabaseUrl = ($env && $env.SUPABASE_URL) ? $env.SUPABASE_URL : 'https://SEU_PROJETO.supabase.co';
const serviceKey  = ($env && $env.SUPABASE_SERVICE_KEY) ? $env.SUPABASE_SERVICE_KEY : 'SUA_SERVICE_KEY';

const dataInicio = new Date();
dataInicio.setDate(dataInicio.getDate() - parseInt(dias || 90));

try {
  const result = await this.helpers.httpRequest({
    method: 'GET',
    url: supabaseUrl + '/rest/v1/sales',
    headers: { apikey: serviceKey, Authorization: 'Bearer ' + serviceKey },
    qs: {
      owner_id: 'eq.' + owner_id,
      created_at: 'gte.' + dataInicio.toISOString(),
      select: 'product_name,quantity,unit_price,total_price,created_at',
      order: 'created_at.desc',
      limit: '2000'
    }
  });
  return JSON.stringify(result);
} catch (e) {
  return JSON.stringify({ error: e.message, tool: 'historico_vendas' });
}

const { latitude = -23.5505, longitude = -46.6333 } = query;

try {
  const result = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.open-meteo.com/v1/forecast',
    qs: {
      latitude: latitude,
      longitude: longitude,
      daily: 'temperature_2m_max,temperature_2m_min,precipitation_sum,weathercode,precipitation_probability_max',
      timezone: 'America/Sao_Paulo',
      forecast_days: '7'
    }
  });
  return JSON.stringify(result);
} catch (e) {
  return JSON.stringify({ error: e.message, tool: 'previsao_tempo' });
}

